use moloch_live_runtime::{dispatch::DispatchLog,execution_edge as edge,maker_policy};
use maker_policy::*;
use baal_transport_service::{Scope,Permit,RequestSpec};
use moloch_replay::session::Session;
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::path::PathBuf;
const BASE:u64=1_792_022_400_000;
static NEXT_FIXTURE:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
fn iso(t:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+t)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn hash(v:&Value)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(v).unwrap()))}
fn config()->edge::Config{edge::Config{fill_window_ms:10_000,markout_ms:60_000,post_window_ms:500,embargo_ms:500,maximum_book_age_ms:10_000,maximum_delivery_ms:1000,continuity_proof_grace_ms:0,maximum_training_age_ms:600_000,minimum_samples:2,minimum_coverage_bps:9000,probability_haircut_bps:0,uncertainty_per_share:1000,exit_fee_per_share:0,fee_policy_source_sha256:"a".repeat(64),maximum_keys:16,maximum_pending:16,retained_samples:8}}
struct F{root:PathBuf,bank:Session,log:DispatchLog,scope:Scope,seq:u64,book:u64}
impl Drop for F{fn drop(&mut self){edge::clear_observer();let _=moloch_live_runtime::execution_distribution::initialize_observer(&self.bank,None);let _=std::fs::remove_dir_all(&self.root);}}
impl F{
 fn new()->Self{let root=std::env::temp_dir().join(format!("maker-policy-{}-{}",std::process::id(),NEXT_FIXTURE.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));std::fs::create_dir(&root).unwrap();let policy=json!({"initialCash":"1000.000000","maximumCommitted":"400.000000","maximumMarketCost":"200.000000","quantity":2,"maximumMarkets":3,"minimumSpreadTicks":2,"entryStopAt":iso(1_000_000),"maximumInventoryAgeMs":60_000,"inventoryAgeClock":"execution","inventoryExitMode":"fixedGain","inventoryMinimumGain":"0.005000","inventoryTakerAfterMs":0});let seed=json!({"runId":"maker-fixture","availableCash":"1000.000000","accountSnapshotHash":"a".repeat(64),"observedAt":iso(0)});let bank=Session::open_live(&root.join("bank"),&policy,&seed).unwrap();let log=DispatchLog::open(&root.join("ordinary.ndjson")).unwrap();let scope=Scope{tournament_id:"cup".into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"201".into())].into()};edge::initialize_observer(&bank,Some(config())).unwrap();let mut f=Self{root,bank,log,scope,seq:0,book:0};f.source(0,"0.400000","0.450000");f.source(3000,"0.400000","0.450000");f}
 fn put(&mut self,mut event:Value,at:u64){event["receivedAt"]=json!(iso(at));event["processedAt"]=json!(iso(at));self.seq+=1;assert!(self.bank.accept("moloch-live",self.seq,&event).unwrap());edge::observe_runtime_committed(&self.bank,"moloch-live",self.seq,&event);moloch_live_runtime::execution_distribution::observe_runtime_committed(&self.bank,"moloch-live",self.seq,&event);}
 fn source(&mut self,at:u64,bid:&str,ask:&str){self.put(json!({"type":"coverage","tournamentId":"cup","marketId":"201","exchangeId":"101","from":chrono::DateTime::from_timestamp_millis(BASE as i64-1000).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),"to":iso(at),"complete":true,"projectedThroughSequence":"999999"}),at);self.book+=1;self.put(json!({"type":"book","book":{"tournamentId":"cup","marketId":"201","exchangeId":"101","sequence":self.book.to_string(),"sourceAt":iso(at),"requestStartedAt":iso(at),"receivedAt":iso(at),"bids":[{"price":bid,"quantity":1000}],"asks":[{"price":ask,"quantity":1000}]}}),at);}
 fn q(&self)->Value{self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="buy"&&q["side"]=="YES"&&q["price"]=="0.400000").unwrap()}
 fn settings(&self)->Settings{let report=self.bank.engine().report().unwrap();Settings{joint_execution:None,authorization_id:"explicit-fixture-review".into(),reviewed_at_ms:BASE+3000,review_source_sha256:"b".repeat(64),bank_manifest_hash:self.bank.manifest_hash().as_str().unwrap().into(),run_id:"maker-fixture".into(),baseline_native_head:self.bank.durable_head(),baseline_report_sha256:hash(&report),baseline_new_trading_realized:report["realized"].as_str().unwrap().into(),exploration_maximum_order_notional:"20.000000".into(),exploration_maximum_deployed_notional:"100.000000".into(),exploration_maximum_quantity:100,additional_realized_loss_stop:"20.000000".into(),expected_inventory_age_ms:60_000,additional_portfolio_charge:"0.000000".into()}}
 fn review(&self)->Reviewed{Reviewed::load(self.settings(),&self.bank).unwrap()}
 fn decide(&self,r:&Reviewed,at:u64)->Decision{decide(&self.bank,&self.scope,&self.log,r,self.q()["id"].as_u64().unwrap(),BASE+at).unwrap()}
 fn attempt(&mut self,q:&Value,at:u64){let id=q["id"].as_u64().unwrap();self.log.append(json!({"kind":"intent","qid":id,"quote":q,"at":iso(at)})).unwrap();self.log.append(json!({"kind":"attempt","qid":id,"at":iso(at)})).unwrap();edge::track_runtime_attempt(&self.bank,&self.log,id,BASE+at);}
 fn actual(&mut self,q:&Value,kind:&str,at:u64,n:u64,fill:&str){let id=q["id"].as_u64().unwrap();self.put(json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":id,"actualOrderId":format!("90{id}"),"marketId":"201","exchangeId":"101","side":q["side"],"action":q["action"],"quantity":n,"price":q["price"],"fillId":fill,"executedAt":iso(at),"fee":"0.000000","status":"filled","filledQuantity":q["quantity"],"fillsComplete":true}),at);if kind=="actual_order_ack"&&self.log.attempted.contains(&id){self.log.append(json!({"kind":"ack","qid":id,"receipt":{"orderId":format!("90{id}")}})).unwrap();}if kind=="actual_order_terminal"&&self.log.acknowledgments.contains_key(&id){self.log.append(json!({"kind":"closed","qid":id})).unwrap();}}
 fn request(&self,q:&Value)->(RequestSpec,Permit){let body=json!({"tournamentId":"cup","exchangeId":"101","side":"yes","action":"buy","quantity":q["quantity"],"price":0.4,"expirationDate":iso(q["expiresAt"].as_u64().unwrap()-BASE),"idempotencyKey":format!("maker-fixture:{}",q["id"])});(RequestSpec{method:"POST".into(),endpoint:"/orders".into(),body_json:Some(serde_json::to_string(&body).unwrap()),body:Some(body)},Permit{run_id:"maker-fixture".into(),intent_id:q["id"].to_string(),owner:"Codex".into(),expires_at_ms:q["expiresAt"].as_u64().unwrap(),maximum_quantity:2,maximum_cost:"0.800000".into()})}
 fn retire(&mut self,at:u64){for q in self.bank.engine().order_records(){let id=q["id"].as_u64().unwrap();if q["retired"]==false&&!self.bank.engine().live_order_bindings().contains_key(&id){self.put(json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","receiptHash":"d".repeat(64),"orderId":id,"confirmedNetworkAttempts":0,"deferPlanningForPackage":true}),at);}}}
 fn cohort(&mut self,base:u64,mark_bid:&str){if base>0{self.source(base,"0.400000","0.450000");self.source(base+3000,"0.400000","0.450000");}let q=self.q();self.attempt(&q,base+3000);self.actual(&q,"actual_order_ack",base+3100,2,"");self.actual(&q,"actual_fill",base+3500,2,&format!("1{}",q["id"]));self.actual(&q,"actual_order_terminal",base+3600,2,"");self.retire(base+3601);self.source(base+63_500,mark_bid,if mark_bid=="0.420000"{"0.470000"}else{"0.430000"});self.source(base+67_000,mark_bid,if mark_bid=="0.420000"{"0.470000"}else{"0.430000"});let exit=self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="sell"&&q["side"]=="YES").expect("actual owned exit");self.actual(&exit,"actual_order_ack",base+67_100,2,"");self.actual(&exit,"actual_fill",base+67_200,2,&format!("2{}",exit["id"]));self.actual(&exit,"actual_order_terminal",base+67_300,2,"");self.retire(base+68_000);}
 fn no_quote(&self)->Value{self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="buy"&&q["side"]=="NO"&&q["price"]=="0.550000").unwrap()}
 fn cohort_no(&mut self,base:u64){self.source(base,"0.400000","0.450000");self.source(base+3000,"0.400000","0.450000");let q=self.no_quote();self.attempt(&q,base+3000);self.actual(&q,"actual_order_ack",base+3100,2,"");self.actual(&q,"actual_fill",base+3500,2,&format!("3{}",q["id"]));self.actual(&q,"actual_order_terminal",base+3600,2,"");self.retire(base+3601);self.source(base+63_500,"0.370000","0.420000");self.source(base+67_000,"0.370000","0.420000");let exit=self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="sell"&&q["side"]=="NO").expect("actual NO owned exit");self.actual(&exit,"actual_order_ack",base+67_100,2,"");self.actual(&exit,"actual_fill",base+67_200,2,&format!("4{}",exit["id"]));self.actual(&exit,"actual_order_terminal",base+67_300,2,"");self.retire(base+68_000);}
}
#[test]fn cold_actual_observer_explores_with_explicit_non_ev_class(){let f=F::new();let review=f.review();let d=f.decide(&review,3000);assert_eq!(d.class(),Class::Exploration);assert!(d.allowed());assert_eq!(d.proof()["executionAuthority"],false);assert!(d.reason().contains("unqualified"));d.validate_current(&f.bank,&review,&f.log,BASE+3000).unwrap();let(spec,permit)=f.request(&f.q());d.authorize(&f.scope,&spec,&permit,BASE+3000).unwrap();}
#[test]fn no_observer_does_not_become_fake_zero_edge_or_exploration(){let f=F::new();let r=f.review();edge::clear_observer();let d=f.decide(&r,3000);assert_eq!(d.class(),Class::Deferred);assert!(d.reason().contains("observer_unavailable"));}
#[test]fn original_quantity_is_not_resized_to_fit_exploration_cap(){let f=F::new();let mut s=f.settings();s.exploration_maximum_order_notional="0.790000".into();let r=Reviewed::load(s,&f.bank).unwrap();assert_eq!(f.decide(&r,3000).reason(),"exploration_order_cap");}
#[test]fn actual_pending_obligation_counts_even_native_retired_and_open_list_absent(){let mut f=F::new();let q=f.q();let id=q["id"].as_u64().unwrap();f.attempt(&q,3000);f.actual(&q,"actual_order_ack",3100,2,"");assert_eq!(deployed_new_capital(&f.bank,&f.log).unwrap(),800000);f.actual(&q,"actual_fill",3200,1,"1001");assert_eq!(deployed_new_capital(&f.bank,&f.log).unwrap(),800000);assert!(!f.log.closed.contains(&id));}
#[test]fn unknown_attempt_does_not_free_capital(){let mut f=F::new();let q=f.q();f.attempt(&q,3000);assert!(deployed_new_capital(&f.bank,&f.log).is_err());assert!(decide(&f.bank,&f.scope,&f.log,&f.review(),q["id"].as_u64().unwrap(),BASE+3000).is_err());}
#[test]fn token_binds_actual_quote_request_and_network_expiry(){let f=F::new();let r=f.review();let d=f.decide(&r,3000);let(mut spec,p)=f.request(&f.q());spec.body.as_mut().unwrap()["quantity"]=json!(1);spec.body_json=Some(serde_json::to_string(spec.body.as_ref().unwrap()).unwrap());assert!(d.authorize(&f.scope,&spec,&p,BASE+3000).is_err());let(spec,mut p)=f.request(&f.q());p.intent_id="other".into();assert!(d.authorize(&f.scope,&spec,&p,BASE+3000).is_err());let(spec,p)=f.request(&f.q());assert!(d.authorize(&f.scope,&spec,&p,BASE+13000).is_err());}
#[test]fn native_commit_dispatch_change_and_observer_reset_revoke_token(){for case in 0..3{let mut f=F::new();let r=f.review();let d=f.decide(&r,3000);match case{0=>f.put(json!({"type":"tick"}),3001),1=>f.log.append(json!({"kind":"source","qid":0,"at":iso(3000)})).unwrap(),_=>edge::initialize_observer(&f.bank,Some(config())).unwrap()}assert!(d.validate_current(&f.bank,&r,&f.log,BASE+3001).is_err());}}
#[test]fn horizon_mismatch_cannot_use_one_second_markout_for_sixty_second_exit(){let f=F::new();let mut s=f.settings();s.expected_inventory_age_ms=1000;assert!(Reviewed::load(s,&f.bank).is_err());let r=f.review();let mut c=config();c.markout_ms=1000;edge::initialize_observer(&f.bank,Some(c)).unwrap();assert_eq!(f.decide(&r,3000).class(),Class::Deferred);}
#[test]fn policy_cannot_increase_human_review_caps_or_relabel_baseline(){let f=F::new();for case in 0..5{let mut s=f.settings();match case{0=>s.exploration_maximum_order_notional="20.000001".into(),1=>s.exploration_maximum_deployed_notional="100.000001".into(),2=>s.additional_realized_loss_stop="20.000001".into(),3=>s.baseline_new_trading_realized="-1.000000".into(),_=>s.run_id="foreign".into()}assert!(Reviewed::load(s,&f.bank).is_err());}}
#[test]fn full_loss_non_full_fill_charge_is_explicit_conservative_policy(){assert_eq!(partial_risk_charge(800000,9000).unwrap(),80000);assert_eq!(partial_risk_charge(1,9999).unwrap(),1);assert_eq!(partial_risk_charge(800000,10000).unwrap(),0);assert!(partial_risk_charge(1,10001).is_err());assert!(partial_risk_charge(i128::MAX,0).is_err());}
#[test]fn two_genuine_complete_positive_cohorts_qualify_actual_observer_gate(){let mut f=F::new();f.cohort(0,"0.420000");f.cohort(80_000,"0.420000");f.source(160_000,"0.400000","0.450000");let r=f.review();let d=f.decide(&r,160_000);assert_eq!(d.class(),Class::Qualified,"{}",d.reason());assert_eq!(d.proof()["model"]["estimate"]["valid_marks"],2);assert!(d.proof()["model"]["estimated_net_gain_units"].as_i64().unwrap()>0);}
#[test]fn adequately_covered_negative_markout_vetoes_even_small_exploration(){let mut f=F::new();f.cohort(0,"0.380000");f.cohort(80_000,"0.380000");f.source(160_000,"0.400000","0.450000");let d=f.decide(&f.review(),160_000);assert_eq!(d.class(),Class::Deferred);assert_eq!(d.reason(),"covered_empirical_nonpositive_markout_veto");}
#[test]fn frozen_physical_ready_cannot_reuse_another_quote_or_report(){let f=F::new();let d=f.decide(&f.review(),3000);let q=f.q();let id=q["id"].as_u64().unwrap();let report=f.bank.engine().report().unwrap();d.validate_frozen(&q,&report,id,BASE+3000).unwrap();let mut changed=report;changed["cash"]=json!("9999.000000");assert!(d.validate_frozen(&q,&changed,id,BASE+3000).is_err());assert!(d.validate_frozen(&q,&f.bank.engine().report().unwrap(),id+1,BASE+3000).is_err());}
#[test]fn candidate_and_actual_ack_obligation_share_exploration_cap_not_native_draft_size(){let mut f=F::new();let q=f.q();f.attempt(&q,3000);f.actual(&q,"actual_order_ack",3100,2,"");let candidate=f.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["side"]=="NO"&&q["action"]=="buy").unwrap();let mut s=f.settings();s.exploration_maximum_order_notional="1.200000".into();s.exploration_maximum_deployed_notional="1.200000".into();let r=Reviewed::load(s,&f.bank).unwrap();let d=decide(&f.bank,&f.scope,&f.log,&r,candidate["id"].as_u64().unwrap(),BASE+3100).unwrap();assert_eq!(d.reason(),"exploration_deployed_cap");}
#[test]fn immutable_loss_stop_survives_policy_reload_without_resetting_baseline(){let mut f=F::new();let mut settings=f.settings();settings.additional_realized_loss_stop="0.010000".into();let r=Reviewed::load(settings.clone(),&f.bank).unwrap();f.cohort(0,"0.380000");f.source(80_000,"0.400000","0.450000");let d=f.decide(&r,80_000);assert_eq!(d.reason(),"exploration_realized_loss_cap");let reloaded=Reviewed::load(settings,&f.bank).unwrap();assert_eq!(f.decide(&reloaded,80_000).reason(),"exploration_realized_loss_cap");}
#[test]fn adopted_fifo_lots_are_not_relabelled_new_exploration_capital(){use moloch_live_runtime::inventory;use baal_transport_service::Receipt;let mut f=F::new();f.retire(3001);let receipt=Receipt{endpoint:"/tournaments/cup/portfolio/positions".into(),status:200,request_started_at:iso(3002),received_at:iso(3003),data:json!({"positions":[{"exchangeId":"101","marketId":"201","quantity":5,"costBasis":2.0,"avgCost":0.4,"lots":[{"lotId":"701","quantity":5,"side":"YES","entryPrice":0.4,"openedAt":iso(0)}]}],"summary":{"totalCostBasis":2.0}})};let event=inventory::adoption(&receipt,f.bank.engine(),"cup","cup",&f.scope.exchanges,&iso(3004)).unwrap();f.put(event,3004);assert_eq!(f.bank.engine().wallet.owned_cost(),2_000_000);assert_eq!(deployed_new_capital(&f.bank,&f.log).unwrap(),0);}
#[test]fn wrong_model_horizon_is_static_validation_error_and_runtime_entry_defer(){let mut f=F::new();let r=f.review();let mut c=config();c.markout_ms=30_000;assert!(r.validate_model(&c).is_err());edge::initialize_observer(&f.bank,Some(c)).unwrap();f.source(4000,"0.400000","0.450000");let d=f.decide(&r,4000);assert_eq!(d.class(),Class::Deferred);assert_eq!(d.reason(),"model_horizon_mismatch");}
#[test]fn opaque_rank_preserves_input_fairness_for_exploration_ties(){let f=F::new();let r=f.review();let yes=f.decide(&r,3000);let no=decide(&f.bank,&f.scope,&f.log,&r,f.no_quote()["id"].as_u64().unwrap(),BASE+3000).unwrap();assert_eq!(yes.class(),Class::Exploration);assert_eq!(no.class(),Class::Exploration);assert_eq!(rank(&[&no,&yes],BASE+3000).unwrap(),vec![0,1]);assert_eq!(rank(&[&yes,&no],BASE+3000).unwrap(),vec![0,1]);}
#[test]fn actual_qualified_cohorts_rank_before_other_untrained_side(){let mut f=F::new();f.cohort(0,"0.420000");f.cohort(80_000,"0.420000");f.source(160_000,"0.400000","0.450000");let r=f.review();let yes=f.decide(&r,160_000);let no=decide(&f.bank,&f.scope,&f.log,&r,f.no_quote()["id"].as_u64().unwrap(),BASE+160_000).unwrap();assert_eq!(yes.class(),Class::Qualified);assert_eq!(no.class(),Class::Exploration);assert_eq!(rank(&[&no,&yes],BASE+160_000).unwrap(),vec![1,0]);}
#[test]fn actual_distinct_qualified_scores_use_exact_capital_time_not_input_order(){let mut f=F::new();f.cohort(0,"0.420000");f.cohort(80_000,"0.420000");f.cohort_no(160_000);f.cohort_no(240_000);f.source(320_000,"0.400000","0.450000");let r=f.review();let yes=f.decide(&r,320_000);let no=decide(&f.bank,&f.scope,&f.log,&r,f.no_quote()["id"].as_u64().unwrap(),BASE+320_000).unwrap();let y=yes.candidate().expect("real qualified YES");let n=no.candidate().expect("real qualified NO");assert_eq!(y.net_gain_units,38_000);assert_eq!(n.net_gain_units,58_000);assert_eq!(y.gross_funding_units,800_000);assert_eq!(n.gross_funding_units,1_100_000);assert_eq!(rank(&[&yes,&no],BASE+320_000).unwrap(),vec![1,0]);assert_eq!(rank(&[&no,&yes],BASE+320_000).unwrap(),vec![0,1]);}
#[test]fn exact_model_token_deadline_has_specific_expiry_without_bank_or_log_mutation(){let f=F::new();let r=f.review();let d=f.decide(&r,3000);let before=f.bank.durable_head();let log=f.log.proof(0);d.validate_current(&f.bank,&r,&f.log,BASE+12_999).unwrap();assert_eq!(d.validate_current(&f.bank,&r,&f.log,BASE+13_000).unwrap_err().to_string(),"MAKER_DECISION_EXPIRED");assert!(rank(&[&d],BASE+13_000).unwrap().is_empty());assert_eq!(f.bank.durable_head(),before);assert_eq!(f.log.proof(0),log);}
#[test]fn exact_native_quote_expiry_is_specific_error_without_state_change(){let f=F::new();let r=f.review();let q=f.q();let head=f.bank.durable_head();let original_log=f.log.proof(0);let at=q["expiresAt"].as_u64().unwrap();assert_eq!(decide(&f.bank,&f.scope,&f.log,&r,q["id"].as_u64().unwrap(),at).err().unwrap().to_string(),"MAKER_QUOTE_EXPIRED");assert_eq!(f.bank.durable_head(),head);assert_eq!(f.log.proof(0),original_log);}
#[test]fn ranking_refuses_cross_bank_and_cross_review_contexts(){let mut f=F::new();let r=f.review();let first=f.decide(&r,3000);f.put(json!({"type":"tick"}),3001);let next=f.decide(&r,3001);assert!(rank(&[&first,&next],BASE+3001).is_err());assert!(rank(&[],BASE+3001).unwrap().is_empty());}
#[test]fn genuine_owned_sell_management_ranks_before_new_exploration(){let mut f=F::new();let q=f.q();f.attempt(&q,3000);f.actual(&q,"actual_order_ack",3100,2,"");f.actual(&q,"actual_fill",3500,2,"1001");f.actual(&q,"actual_order_terminal",3600,2,"");f.retire(3601);f.source(6000,"0.400000","0.450000");f.source(9000,"0.400000","0.450000");f.scope.exchanges.insert("102".into(),"202".into());f.put(json!({"type":"book","book":{"tournamentId":"cup","marketId":"202","exchangeId":"102","sequence":"1","sourceAt":iso(9000),"requestStartedAt":iso(9000),"receivedAt":iso(9000),"bids":[{"price":"0.400000","quantity":1000}],"asks":[{"price":"0.450000","quantity":1000}]}}),9000);let records=f.bank.engine().order_records();let exit=records.iter().find(|q|q["retired"]==false&&q["action"]=="sell"&&q["exchangeId"]=="101").unwrap();let entry=records.iter().find(|q|q["retired"]==false&&q["action"]=="buy"&&q["exchangeId"]=="102").unwrap();let r=f.review();let sell=decide(&f.bank,&f.scope,&f.log,&r,exit["id"].as_u64().unwrap(),BASE+9000).unwrap();let buy=decide(&f.bank,&f.scope,&f.log,&r,entry["id"].as_u64().unwrap(),BASE+9000).unwrap();assert_eq!(sell.class(),Class::OwnedExit);assert_eq!(buy.class(),Class::Exploration);assert_eq!(rank(&[&buy,&sell],BASE+9000).unwrap(),vec![1,0]);}

fn joint_config()->moloch_live_runtime::execution_distribution::Config{moloch_live_runtime::execution_distribution::Config{markout_ms:60000,post_window_ms:1000,maximum_book_age_ms:10000,maximum_delivery_ms:1000,block_ms:60000,minimum_blocks:20,minimum_completed:100,retained_samples:128,maximum_pending:128,shrinkage_strength:4,minimum_value_coverage_bps:10000,uncertainty_floor_per_share:1000,tail_charge_per_filled_share:500,write_charge_per_order:100,capital_charge_per_million_unit_ms:1,fee_policy_source_sha256:"a".repeat(64),exit_fee_per_share:0}}
fn joint_config_sha(c:&moloch_live_runtime::execution_distribution::Config)->String{format!("{:x}",Sha256::digest(serde_json::to_vec(c).unwrap()))}
fn joint_review(f:&F,c:&moloch_live_runtime::execution_distribution::Config)->Reviewed{let mut s=f.settings();s.joint_execution=Some(JointExecution{version:1,distribution_config_sha256:joint_config_sha(c),minimum_completed:100,minimum_time_blocks:20,minimum_per_class:1});Reviewed::load(s,&f.bank).unwrap()}
#[test]fn joint_option_omission_preserves_exact_legacy_settings_hash(){let f=F::new();let s=f.settings();let mut value=serde_json::to_value(&s).unwrap();assert!(value.get("jointExecution").is_none());let sha=f.review().sha256().to_owned();value["jointExecution"]=Value::Null;let decoded:Settings=serde_json::from_value(value).unwrap();assert_eq!(Reviewed::load(decoded,&f.bank).unwrap().sha256(),sha);}
#[test]fn explicit_joint_profile_refuses_low_counts_bad_config_identity_and_unknown_keys(){let f=F::new();for case in 0..5{let mut s=f.settings();s.joint_execution=Some(JointExecution{version:1,distribution_config_sha256:"a".repeat(64),minimum_completed:100,minimum_time_blocks:20,minimum_per_class:1});let j=s.joint_execution.as_mut().unwrap();match case{0=>j.minimum_completed=99,1=>j.minimum_time_blocks=19,2=>j.minimum_per_class=0,3=>j.distribution_config_sha256="bad".into(),_=>j.version=2};assert!(Reviewed::load(s,&f.bank).is_err());}let mut value=serde_json::to_value(f.settings()).unwrap();value["jointExecution"]=json!({"version":1,"distributionConfigSha256":"a".repeat(64),"minimumCompleted":100,"minimumTimeBlocks":20,"minimumPerClass":1,"fittedPositiveMean":999});assert!(serde_json::from_value::<Settings>(value).is_err());}
#[test]fn joint_missing_actual_observer_defers_instead_of_inventing_zero_fills_or_confidence(){let f=F::new();let r=joint_review(&f,&joint_config());let d=f.decide(&r,3000);assert_eq!(d.class(),Class::Deferred);assert!(d.reason().contains("joint_observer_unavailable"));assert!(d.proof()["jointExecution"].is_null());}
#[test]fn genuine_joint_cold_start_can_only_use_original_bounded_exploration(){let mut f=F::new();let c=joint_config();moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(c.clone())).unwrap();f.source(4000,"0.400000","0.450000");let r=joint_review(&f,&c);let d=f.decide(&r,4000);assert_eq!(d.class(),Class::Exploration);assert!(d.reason().contains("not_positive_ev"));assert!(d.proof()["jointExecution"]["estimate"].is_null());assert_eq!(d.proof()["partialRiskChargeKind"],"joint_observed_outcomes_no_extra_full_loss_nonfull_charge");d.validate_current(&f.bank,&r,&f.log,BASE+4000).unwrap();let(spec,permit)=f.request(&f.q());d.authorize(&f.scope,&spec,&permit,BASE+4000).unwrap();assert!(d.candidate().is_none());}
#[test]fn joint_exploration_still_applies_original_cap_and_original_loss_bound(){let mut f=F::new();let c=joint_config();moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(c.clone())).unwrap();f.source(4000,"0.400000","0.450000");let mut s=f.settings();s.joint_execution=Some(JointExecution{version:1,distribution_config_sha256:joint_config_sha(&c),minimum_completed:100,minimum_time_blocks:20,minimum_per_class:1});s.exploration_maximum_order_notional="0.790000".into();let r=Reviewed::load(s,&f.bank).unwrap();assert_eq!(f.decide(&r,4000).reason(),"exploration_order_cap");}
#[test]fn joint_config_swap_reset_stale_source_and_wrong_horizon_never_reuse_a_token(){for case in 0..4{let mut f=F::new();let c=joint_config();moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(c.clone())).unwrap();f.source(4000,"0.400000","0.450000");let r=joint_review(&f,&c);let d=f.decide(&r,4000);assert_eq!(d.class(),Class::Exploration);match case{0=>{let mut changed=c;changed.write_charge_per_order+=1;moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(changed)).unwrap();assert!(d.validate_current(&f.bank,&r,&f.log,BASE+4000).is_err());},1=>{moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,None).unwrap();assert!(d.validate_current(&f.bank,&r,&f.log,BASE+4000).is_err());},2=>{assert!(!f.decide(&r,14001).allowed());},_=>{let mut changed=c;changed.markout_ms=30000;moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(changed)).unwrap();assert_eq!(f.decide(&r,4000).reason(),"joint_config_or_horizon_mismatch");}}}}
#[test]fn positive_legacy_cohorts_do_not_qualify_missing_joint_outcomes(){let mut f=F::new();f.cohort(0,"0.420000");f.cohort(80_000,"0.420000");f.source(160_000,"0.400000","0.450000");let legacy=f.review();assert_eq!(f.decide(&legacy,160000).class(),Class::Qualified);let c=joint_config();moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(c.clone())).unwrap();f.source(161000,"0.400000","0.450000");let r=joint_review(&f,&c);let d=f.decide(&r,161000);assert_eq!(d.class(),Class::Exploration);assert!(d.candidate().is_none());assert_eq!(d.proof()["qualificationModel"],"joint_zero_partial_full_v1");}

impl F{
 fn joint_trial(&mut self,review:&Reviewed,base:u64,filled:u64){
  use moloch_live_runtime::{execution_distribution as dist,feedback};use baal_transport_service::Receipt;
  if base>0{self.source(base,"0.400000","0.450000");self.source(base+3000,"0.400000","0.450000");}
  let q=self.q();let qid=q["id"].as_u64().unwrap();let(spec,_)=self.request(&q);let actual=format!("90{qid}");
  self.log.append(json!({"kind":"intent","qid":qid,"quote":q,"spec":spec,"at":iso(base+3000),"maker":{"reviewedSettingsSha256":review.sha256()},"fundamental":null})).unwrap();
  self.log.append(json!({"kind":"attempt","qid":qid,"at":iso(base+3000),"captureAtMs":BASE+base+3000,"nativeHead":self.bank.durable_head(),"dispatchBefore":self.log.proof(qid)})).unwrap();
  edge::track_runtime_attempt(&self.bank,&self.log,qid,BASE+base+3000);dist::track_runtime_attempt(&self.bank,&self.log,qid,BASE+base+3000);
  let receipt=|endpoint:String,data:Value,t:u64|Receipt{endpoint,status:200,request_started_at:iso(t-1),received_at:iso(t),data};
  let ack=receipt("/orders".into(),json!({"orderId":actual,"exchangeId":"101","side":"yes","action":"buy","quantity":2,"price":0.4}),base+3100);
  self.log.append(json!({"kind":"ack","qid":qid,"receipt":ack})).unwrap();self.put(feedback::acknowledgment(&q,&ack,&iso(base+3100)).unwrap(),base+3100);
  let rows=if filled==0{vec![]}else{vec![json!({"id":format!("71{qid}"),"quantity":filled,"side":"yes","price":0.4,"filledAt":iso(base+3500)})]};
  let tape=receipt(format!("/orders/{actual}/fills?limit=200"),json!({"orderId":actual,"exchangeId":"101","tournamentId":"cup","coverage":{"complete":true,"projectedThroughSequence":999999},"pagination":{"hasMore":false,"nextCursor":null,"limit":200},"totalQuantityFilled":filled,"data":rows}),base+4200);
  for event in feedback::fills(&q,&actual,"cup",&tape,&iso(base+4200)).unwrap(){self.put(event,base+4200);}
  let order=receipt(format!("/orders/{actual}"),json!({"id":actual,"exchangeId":"101","tournamentId":"cup","side":"yes","action":"buy","priceLimit":0.4,"quantity":2,"quantityFilled":filled,"open":false,"terminalReasonCode":"Canceled"}),base+4199);
  let terminal=feedback::terminal(&q,&actual,"cup",&order,&tape,&iso(base+4200)).unwrap().unwrap();self.put(terminal,base+4200);
  self.log.append(json!({"kind":"closed","qid":qid,"orderReceiptHash":feedback::digest(&order).unwrap(),"fillReceiptHash":feedback::digest(&tape).unwrap()})).unwrap();dist::confirm_runtime_terminal(&self.bank,&self.log,qid,&order,&tape,BASE+base+4200);
  self.retire(base+4201);self.source(base+63500,"0.420000","0.470000");self.source(base+67000,"0.420000","0.470000");
  if filled>0{let exit=self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["action"]=="sell"&&q["side"]=="YES").unwrap();self.actual(&exit,"actual_order_ack",base+67100,filled,"");self.actual(&exit,"actual_fill",base+67200,filled,&format!("72{qid}"));self.actual(&exit,"actual_order_terminal",base+67300,filled,"");}
  self.retire(base+68000);
 }
}
#[test]fn original_zero_partial_full_receipts_and_actual_capital_release_are_insufficient_without_reviewed_hundred_trials(){
 use moloch_live_runtime::execution_distribution as dist;
 let mut f=F::new();let c=joint_config();dist::initialize_observer(&f.bank,Some(c.clone())).unwrap();
 // The initial book is genuinely observed after this model's cold cursor.
 f.source(3000,"0.400000","0.450000");let r=joint_review(&f,&c);
 f.joint_trial(&r,0,0);f.joint_trial(&r,80000,1);f.joint_trial(&r,160000,2);
 f.source(240000,"0.400000","0.450000");f.source(243000,"0.400000","0.450000");
 let d=f.decide(&r,243000);assert_eq!(dist::observer_diagnostic().unwrap()["disabled"],Value::Null);
 assert_eq!(d.class(),Class::Exploration,"{}",d.reason());let e=&d.proof()["jointExecution"]["estimate"];
 assert_eq!(e["parent_counts"],json!([1,1,1]));assert_eq!(e["parent_completed"],3);assert_eq!(e["value_covered"],3);assert_eq!(e["capital_time_incomplete"],0);assert_eq!(e["unresolved"],0);
 assert_eq!(e["qualified_descriptive_sample"],false);assert!(e["net_shadow_score_per_requested_share"].is_null());assert!(d.proof()["jointExecution"]["netGainUnits"].is_null());assert!(d.candidate().is_none());
}

#[test]fn joint_review_uses_original_typed_config_bytes_from_actual_observer(){
 let f=F::new();let c=joint_config();moloch_live_runtime::execution_distribution::initialize_observer(&f.bank,Some(c.clone())).unwrap();
 let(original,sha)=moloch_live_runtime::execution_distribution::runtime_configuration(&f.bank).unwrap();
 assert_eq!(sha,joint_config_sha(&c));assert_eq!(serde_json::to_vec(&original).unwrap(),serde_json::to_vec(&c).unwrap());
 assert_ne!(sha,hash(&serde_json::to_value(&c).unwrap()),"reserializing a Value changes this typed source identity");
 let r=joint_review(&f,&c);assert_ne!(r.sha256(),f.review().sha256());
}
